const item = $input.first().json.body || $input.first().json;

const listingId = item.listingId || 101;
const listingTitle = item.listingTitle || 'Pre-loved Sofa Set';
const originalPrice = Number(item.originalPrice || 12000);
const offerPrice = Number(item.offerPrice || 9000);
const buyerName = item.buyerName || 'Neighbor';
const buyerNote = item.buyerNote || '';
const daysActive = Number(item.daysActive || 5);

const prompt = `You are the Friendly Community Trade Arbitrator for Mana Community Resident Marketplace.
Evaluate a buyer's price offer and advise the seller on negotiation strategy while preserving neighborly harmony:

Trade Context:
- Item: ${listingTitle} (ID: ${listingId})
- Listed Asking Price: ₹${originalPrice}
- Buyer Offer: ₹${offerPrice} (from ${buyerName})
- Buyer Message: "${buyerNote}"
- Days on Marketplace: ${daysActive} days

Arbitration Directives:
1. Calculate discount: ${Math.round(((originalPrice - offerPrice) / Math.max(1, originalPrice)) * 100)}% off.
2. Lowball Scoring:
   - Discount <= 15%: FAIR_OFFER (Recommended to accept or round off).
   - Discount 16%–35%: SLIGHT_LOWBALL (Counter-offer recommended).
   - Discount > 35%: SEVERE_LOWBALL (Counter firmly or politely decline).
3. Compute a win-win counter price that gives buyer a fair concession while protecting seller's return.
4. Compose a warm, polite WhatsApp/Mana chat message from seller to buyer.

Respond ONLY with a valid JSON object matching this schema:
{
  "offerAssessment": "FAIR_OFFER" | "SLIGHT_LOWBALL" | "SEVERE_LOWBALL",
  "discountPercentage": number,
  "recommendedAction": "ACCEPT" | "COUNTER" | "DECLINE",
  "recommendedCounterPrice": number,
  "sellerAdvisory": string,
  "suggestedNeighborReply": string
}`;

return [{ json: { prompt, listingId, listingTitle, originalPrice, offerPrice, buyerName } }];

const raw = $input.first().json;
let parsed;

try {
  const content = raw.candidates?.[0]?.content?.parts?.[0]?.text;
  if (content) {
    const cleaned = content.replace(/^\s*\`\`\`json\s*|\s*\`\`\`\s*$/g, '').trim();
    parsed = JSON.parse(cleaned);
  }
} catch (e) {}

if (!parsed || !parsed.offerAssessment) {
  const orig = raw.originalPrice || 10000;
  const off = raw.offerPrice || 8000;
  const discount = Math.round(((orig - off) / Math.max(1, orig)) * 100);
  const counter = Math.round((orig + off) / 2);
  const isSevere = discount > 35;
  const isFair = discount <= 15;

  parsed = {
    offerAssessment: isFair ? "FAIR_OFFER" : isSevere ? "SEVERE_LOWBALL" : "SLIGHT_LOWBALL",
    discountPercentage: discount,
    recommendedAction: isFair ? "ACCEPT" : isSevere ? "DECLINE" : "COUNTER",
    recommendedCounterPrice: counter,
    sellerAdvisory: isFair
      ? "Great offer close to asking price. Recommended to accept for quick doorstep handover."
      : isSevere
      ? "Offer represents a steep discount. You can counter at a reasonable middle ground or decline."
      : "Standard resident negotiation. Meeting halfway protects value while keeping transaction active.",
    suggestedNeighborReply: `Hi ${raw.buyerName || 'Neighbor'}, thank you for your interest in "${raw.listingTitle || 'the item'}"! ₹${off.toLocaleString('en-IN')} is slightly below my expectation, but as we live in the same community, I can happily meet you at ₹${counter.toLocaleString('en-IN')}. Let me know if that works for you! 😊`
  };
}

return [{
  json: {
    status: "success",
    listingId: raw.listingId,
    itemTitle: raw.listingTitle,
    analyzedAt: new Date().toISOString(),
    negotiation: parsed
  }
}];
